// === Tab: mySketch ===
// let Risou
// https://risoume.github.io/

let n, m, k;
let s, mult;
let l = 60;

Grid[][] grids;

function setup() {
  createCanvas(600, 600);
  noFill();
  noLoop();
  init();
}

function init() {
  //n = int(random(4, 8));
  n = 12;
  m = 12;
  s = (width-2*l)/m;
  grids = new Array(n)[m];
  k = 0;
  mult = 1;
  for (i = 0; i < n; i++) {
    for (j = 0; j < m; j++) {
      grids[i][j] = new Grid(l+i*s, l+j*s, s*mult);
    }
  }
}

function draw() {
  background("#db3a34");
  //strokeWeight(0.8);
  for (i = 0; i < n; i++) {
    for (j = 0; j < m; j++) {
      grids[i][j].display(i, j);
    }
  }
}

class Grid {
  x, y, d, r, t;

  constructor(tx, ty, tsz) {
    x = tx;
    y = ty;
    d = tsz;
    r = d/2;
  }

  function display(p, q) {
    pushMatrix();
    translate(x+d/2, y+d/2);
    beginShape();
    //for (i = 0; i < (p+1)*4; i++) {
    for (i = 0; i < (p+1)*(q+1); i++) {
    //for (i = 0; i < p*n+q+1; i++) {
      //t = random(2*(p+1)*PI/n);
      t = PI*random(2);
      vertex(r*cos(t), r*sin(t));
    }
    endShape(CLOSE);
    popMatrix();
  }
}

function mouseReleased() {
  init();
  redraw();
}

